mapper.select:
select li.info_id, li.user_name, li.ipaddr, li.status, li.msg, li.access_time
from sys_logininfor li left join sys_user u on u.user_name = li.user_name


		AND li.ipaddr like concat('%', #{ipaddr}, '%')


		AND li.status = #{status}


		AND li.user_name like concat('%', #{userName}, '%')


		AND li.access_time >= #{params.beginTime}


		AND li.access_time <= #{params.endTime}

	${params.dataScope}

order by li.info_id desc
